//! The engine against vectors of the Python engine's own semantics
//! (`tests/vectors/mana.json`, generated by `scripts/parity/vectors.py`;
//! regenerate with `cargo xtask vectors`): mana-cost parsing and the
//! pool's payment order, where the F0 tie-breaks live.

use std::collections::BTreeMap;
use std::path::PathBuf;

use mtgrules::manasys::{ManaPool, land_mana_types, mana_order, parse_cost};
use serde::Deserialize;

fn vector_file(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/vectors")
        .join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("reading {}: {e}", path.display()))
}

#[derive(Deserialize)]
struct CostCase {
    cost: String,
    generic: i64,
    pips: BTreeMap<String, i64>,
    hybrid: Vec<Vec<String>>,
    colorless: i64,
    x_count: i64,
    mv: i64,
}

#[derive(Deserialize)]
struct PoolCase {
    added: Vec<(String, i64)>,
    cost: String,
    can_pay: bool,
    paid: bool,
    after: BTreeMap<String, i64>,
}

#[derive(Deserialize)]
struct OrderCase {
    types: Vec<String>,
    ordered: Vec<String>,
}

#[derive(Deserialize)]
struct LandCase {
    colors: Vec<String>,
    types: Vec<String>,
    any: bool,
}

#[derive(Deserialize)]
struct ManaVectors {
    costs: Vec<CostCase>,
    pools: Vec<PoolCase>,
    order: Vec<OrderCase>,
    lands: Vec<LandCase>,
}

#[test]
fn mana_system_matches_the_python_engine() {
    let vectors: ManaVectors =
        serde_json::from_str(&vector_file("mana.json")).expect("mana.json parses");
    assert!(vectors.costs.len() >= 10 && vectors.pools.len() >= 10);
    for case in &vectors.costs {
        let cost = parse_cost(&case.cost);
        assert_eq!(cost.generic, case.generic, "generic of {:?}", case.cost);
        let pips: BTreeMap<String, i64> = cost.pips.iter().map(|(k, v)| (k.clone(), *v)).collect();
        assert_eq!(pips, case.pips, "pips of {:?}", case.cost);
        let hybrid: Vec<Vec<String>> = cost
            .hybrid
            .iter()
            .map(|h| h.iter().cloned().collect())
            .collect();
        assert_eq!(hybrid, case.hybrid, "hybrid of {:?}", case.cost);
        assert_eq!(
            (cost.colorless, cost.x_count, cost.mv()),
            (case.colorless, case.x_count, case.mv),
            "{:?}",
            case.cost
        );
    }
    for case in &vectors.pools {
        let mut pool = ManaPool::new();
        for (mana_type, n) in &case.added {
            pool.add(mana_type, *n);
        }
        let cost = parse_cost(&case.cost);
        assert_eq!(
            pool.can_pay(&cost),
            case.can_pay,
            "can_pay {:?} from {:?}",
            case.cost,
            case.added
        );
        assert_eq!(
            pool.pay(&cost),
            case.paid,
            "pay {:?} from {:?}",
            case.cost,
            case.added
        );
        let after: BTreeMap<String, i64> = pool.mana.iter().map(|(k, v)| (k.clone(), *v)).collect();
        assert_eq!(
            after, case.after,
            "pool after paying {:?} from {:?}",
            case.cost, case.added
        );
    }
    for case in &vectors.order {
        assert_eq!(
            mana_order(&case.types),
            case.ordered,
            "mana_order({:?})",
            case.types
        );
    }
    for case in &vectors.lands {
        let (types, any) = land_mana_types(&case.colors);
        assert_eq!(
            (types, any),
            (case.types.clone(), case.any),
            "land_mana_types({:?})",
            case.colors
        );
    }
}
